mapper.select:
SELECT id, tenant_id, principal_id, member_kind, status, generation, version,
    valid_from, valid_to, sponsor_membership_id
FROM auth_governance.membership WHERE id = #{id}

SELECT source_system, source_tenant_ref, source_subject_ref, principal_id, membership_id, tenant_id
FROM auth_governance.legacy_identity_binding WHERE source_system = #{sourceSystem}
    AND source_tenant_ref = #{sourceTenantRef} AND source_subject_ref = #{sourceSubjectRef}

SELECT payload_hash, result_ref, completed FROM auth_governance.command_record
WHERE operator_ref = #{operatorRef} AND tenant_id = #{tenantId}
    AND operation = #{operation} AND command_id = #{commandId} FOR UPDATE

mapper.update:
UPDATE auth_governance.command_record SET completed = true, result_ref = #{resultRef}
WHERE operator_ref = #{operatorRef} AND tenant_id = #{tenantId} AND operation = #{operation}
    AND command_id = #{commandId} AND completed = false

UPDATE auth_governance.membership SET status = #{newStatus}, version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND version = #{expectedVersion} AND status = #{oldStatus}
